changeSet.sql:
create index ix_transaction_record__fraud_queue on transaction_record (fraud_status, transaction_date desc)
    where fraud_status <> 'CLEAN';
create index if not exists ix_transaction_record__sender_date on transaction_record (sender_id, transaction_date);
create index if not exists ix_transaction_record__receiver_date on transaction_record (receiver_id, transaction_date);

rollback.sql:
drop index if exists ix_transaction_record__fraud_queue;
drop index if exists ix_transaction_record__sender_date;
drop index if exists ix_transaction_record__receiver_date;
